SELECT cp.cp_department, hd.hd_buy_potential, SUM(cs.cs_net_paid) AS total_net_paid, COUNT(DISTINCT cs.cs_order_number) AS distinct_orders, (SELECT MAX(cr2.cr_return_amount) FROM catalog_returns cr2 WHERE cr2.cr_returned_date_sk = 2451112) AS sample_return_amount FROM catalog_sales cs JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN catalog_returns cr ON cr.cr_order_number = cs.cs_order_number WHERE cp.cp_type = 'monthly' GROUP BY cp.cp_department, hd.hd_buy_potential HAVING SUM(cs.cs_net_paid) > 424.55
